files.content:
html {
  block-size: 100%;
}

body {
  min-block-size: 100%;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background-color: #000;
}

.header {
  display: flex;
  align-items: center;
  min-block-size: 5em;
  padding: 0 4em;
}

.gallery {
  grid-auto-flow: dense;
  display: grid;
  grid-template-columns: repeat(4, 1fr) 2fr 200px;
  grid-template-rows: repeat(6, 1fr);
  gap: 10px;
  box-sizing: border-box;
  min-block-size: calc(100vh - 5em);
  padding: 0 4em 4em;
}

.gallery__item {
  box-sizing: border-box;
  min-block-size: 4.3em;
  margin: 0;
}

.gallery__image {
  inline-size: 100%;
  block-size: 100%;
  max-block-size: 100%;
  object-fit: cover;
}

.gallery__item:nth-child(7) {
  grid-column: 6 / -1;
  grid-row: 1 / -1;
}

.gallery__item:nth-child(5) {
  grid-column: 4 / 6;
  grid-row: 4 / -1;
}

.gallery__item:nth-child(1) {
  grid-column: span 2;
  grid-row: span 2;
}

.gallery__item:nth-child(3) {
  grid-column: span 2;
  grid-row: span 2;
}

.gallery__item:nth-child(2) {
  grid-column: 3 / 6;
  grid-row: span 3;
}

.gallery__item:nth-child(4) {
  grid-column: 1 / 4;
  grid-row: span 2;
}

@media (width <= 768px) {
  .header {
    padding: 0 1em;
  }

  .gallery {
    padding: 0 1em 1em;
  }
}
